package gui;
import java.awt.*;import javax.swing.*;import javax.swing.table.DefaultTableModel;import datos.DatosSistema;import entidad.*;
public class FormReportes extends JInternalFrame{
 private JTabbedPane tabs;private DefaultTableModel modelPac,modelHist,modelCit;
 public FormReportes(){setTitle("Módulo de Reportes de Análisis");setClosable(true);setMaximizable(true);setIconifiable(true);setBounds(100,50,700,450);getContentPane().setLayout(new BorderLayout());tabs=new JTabbedPane();modelPac=new DefaultTableModel(new Object[]{"ID Paciente","DNI","Nombre","Teléfono"},0);JPanel p=new JPanel(new BorderLayout());p.add(new JScrollPane(new JTable(modelPac)));tabs.addTab("Análisis de Pacientes",p);modelHist=new DefaultTableModel(new Object[]{"ID","Paciente","Diagnóstico","Alergias","Fecha"},0);JPanel h=new JPanel(new BorderLayout());h.add(new JScrollPane(new JTable(modelHist)));tabs.addTab("Análisis de Historial",h);modelCit=new DefaultTableModel(new Object[]{"ID Cita","Fecha","Hora","Paciente","Médico","Estado"},0);JPanel c=new JPanel(new BorderLayout());c.add(new JScrollPane(new JTable(modelCit)));tabs.addTab("Reporte de Citas",c);getContentPane().add(tabs,BorderLayout.CENTER);}
 public void seleccionarPestana(int index){cargarTablas();tabs.setSelectedIndex(index);}
 private void cargarTablas(){modelPac.setRowCount(0);for(Paciente p:DatosSistema.pacientes)modelPac.addRow(new Object[]{p.getId(),p.getDni(),p.getNombre(),p.getTelefono()});modelHist.setRowCount(0);for(HistorialMedico h:DatosSistema.historiales)modelHist.addRow(new Object[]{h.getId(),h.getPaciente().getNombre(),h.getDiagnostico(),h.getAlergias(),h.getFecha()});modelCit.setRowCount(0);for(Cita c:DatosSistema.citas)modelCit.addRow(new Object[]{c.getId(),c.getFecha(),c.getHora(),c.getPaciente().getNombre(),c.getMedico().getNombre(),c.getEstado()});}
}
